import { z } from 'zod';
import i18n from '~/shared/i18n/i18n';

export const RegisterBizNoFormSchema = z.object({
  bizName: z
    .string()
    .min(1, i18n.t('validation:enterNamePrompt'))
    .min(2, i18n.t('validation:enterAtLeastTwoCharacters'))
    //.regex(/^[가-힣\s]+$/, i18n.t('validation:enterKorean'))
    .max(20, i18n.t('validation:enterUpTo20Characters')),
  //.refine((value: string) => !value.includes(' '), { message: i18n.t('validation:noSpacesAllowed') }), // 한글명
  ownerName: z
    .string()
    .min(1, i18n.t('validation:enterNamePrompt'))
    .min(2, i18n.t('validation:enterAtLeastTwoCharacters'))
    //.regex(/^[가-힣\s]+$/, i18n.t('validation:enterKorean'))
    .max(20, i18n.t('validation:enterUpTo20Characters'))
    .refine((value: string) => !value.includes(' '), { message: i18n.t('validation:noSpacesAllowed') }), // 한글명
  openDate: z
    .string()
    .min(1, i18n.t('validation:enterOpenDatePrompt'))
    .min(8, i18n.t('validation:enterOpenDateIn8Digits'))
    .regex(/^(19|20)\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])$/, i18n.t('validation:enterOpenDateInCorrectFormat'))
    .refine((value: string) => !value.includes(' '), { message: i18n.t('validation:noSpacesAllowed') }),
  businessNumber: z
    .string()
    .min(10, i18n.t('validation:enterBusinessNumber'))
    .regex(/^[0-9]+$/, i18n.t('validation:numbersOnlyAllowed'))
    .refine((value: string) => !value.includes(' '), { message: i18n.t('validation:noSpacesAllowed') }),
});
